// ELEMENTS (mockup, top to bottom):
// 1. Hero property photo filling the whole frame (src)
// 2. 'NOVO IMÓVEL' pill, top-left - accent (light gold gradient), bold italic caps
// 3. White price box '450.000 €', right side, straddling the top edge of the band - navy bold italic
// 4. Angled bottom band (higher on the right) - blue gradient, covers the lower ~43%
// 5. Location line 'LISBOA · ALVALADE' - small, wide-tracked caps, white
// 6. Headline 'T3 COM VARANDA' - heavy italic caps, white
// 7. Specs line '120 m² · 3 quartos · 2 WC · garagem' - regular, white
// 8. CTA pill 'Ligue já +351 963 050 290' - accent (light gold gradient), bold italic
// 9. Agent avatar circle, bottom-left (avatar)
// 10. Agent name 'Manuel Reis' - bold, white, beside the avatar
// 11. Brokerage logo, right end of the avatar row (logo)
// 12. Footer small print 'IAD PORTUGAL S.A. | AMI: 11220' - tiny bold caps, white
import React from 'react';
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from 'remotion';
import { FONTS } from '../style-tokens';
import type { PrimitiveProps } from '../primitives';

const NAVY = '#1E3550';
const PLACEHOLDER = '#EEF0EF';
const BLUE_GRADIENT = 'linear-gradient(160deg, #23B6EA 0%, #128FD6 50%, #0A63AE 100%)';
const GOLD_GRADIENT = 'linear-gradient(100deg, #F8E9B8 0%, #EBCD86 50%, #D2AB5E 100%)';

const ImovelRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(10, Math.round((anim.end - anim.start) * fps));
  const p: Record<string, unknown> = anim.params ?? {};
  const str = (k: string) => String(p[k] ?? '').trim();

  const src = str('src');
  const avatar = str('avatar');
  const logo = str('logo');
  const tag = str('tag');
  const price = str('price');
  const location = str('location');
  const title = str('title') || String(anim.text ?? '').trim();
  const specs = str('specs');
  const cta = str('cta');
  const name = str('name');
  const footer = str('footer');

  const wide = format !== 'portrait';
  // mockup unit: the reference is 363px wide in portrait
  const s = wide ? (H / 643) * 1.55 : W / 363;

  // spring that starts at `at` and settles by `at + dur` (fractions of the layer)
  const pop = (at: number, dur: number, damping = 11) =>
    spring({
      frame: f - Math.round(at * L),
      fps,
      config: { damping, stiffness: 150, mass: 0.8 },
      durationInFrames: Math.max(1, Math.round(dur * L)),
    });
  const fade = (v: number) => Math.min(1, Math.max(0, v * 2.5));

  // 1. the image comes first
  const imgOpacity = interpolate(f, [0, Math.max(1, Math.round(0.12 * L))], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const imgScale = interpolate(f, [0, Math.max(2, Math.round(0.32 * L))], [1.14, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });

  const pBand = pop(0.14, 0.2, 18);
  const pTag = pop(0.22, 0.18, 9);
  const pPrice = pop(0.28, 0.18, 9);
  const pLoc = pop(0.3, 0.14, 16);
  const pTitle = pop(0.33, 0.15, 14);
  const pSpecs = pop(0.36, 0.14, 16);
  const pCta = pop(0.4, 0.15, 8);
  const pAvatar = pop(0.45, 0.13, 10);
  const pLogo = pop(0.47, 0.12, 8);
  const pFooter = pop(0.5, 0.1, 18);

  // angled band: top edge higher on the right (~2.4deg)
  const bandRight = (wide ? 0.5 : 0.572) * H;
  const bandLeft = bandRight + W * 0.0413;
  const clip = `polygon(0px ${bandLeft}px, ${W}px ${bandRight}px, ${W}px ${H}px, 0px ${H}px)`;

  const padX = W * (wide ? 0.045 : 0.066);
  const titleSize = 28 * s * Math.min(1, Math.max(0.5, (wide ? 30 : 15) / Math.max(1, title.length)));
  const priceSize = 26 * s * Math.min(1, Math.max(0.55, 10 / Math.max(1, price.length)));

  const rise = (v: number, dist: number): React.CSSProperties => ({
    opacity: fade(v),
    transform: `translateY(${(1 - v) * dist * s}px)`,
  });

  const pill = (text: string, size: number): React.CSSProperties => ({
    display: 'inline-block',
    background: GOLD_GRADIENT,
    color: NAVY,
    fontFamily: FONTS.display,
    fontWeight: 800,
    fontStyle: 'italic',
    fontSize: size,
    lineHeight: 1.15,
    padding: `${size * 0.32}px ${size * 0.8}px`,
    borderRadius: 999,
    boxShadow: `0 ${3 * s}px ${10 * s}px rgba(1,35,66,0.28), inset 0 ${1 * s}px 0 rgba(255,255,255,0.55)`,
    maxWidth: '100%',
    wordBreak: 'break-word',
    textAlign: text.length > 30 ? 'left' : 'center',
  });

  const avatarSize = 26 * s;
  const avatarRow = (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8 * s, minWidth: 0, ...rise(pAvatar, 30) }}>
      <div
        style={{
          width: avatarSize,
          height: avatarSize,
          flexShrink: 0,
          borderRadius: '50%',
          overflow: 'hidden',
          border: `${1.2 * s}px solid rgba(255,255,255,0.85)`,
          background: '#C9CDD1',
          transform: `scale(${pAvatar})`,
        }}
      >
        {avatar ? <Img src={avatar} style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : null}
      </div>
      {name ? (
        <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 11 * s, color: '#FFFFFF', lineHeight: 1.2 }}>
          {name}
        </div>
      ) : null}
    </div>
  );

  const logoBox = (
    <div style={{ opacity: fade(pLogo), transform: `scale(${pLogo})`, transformOrigin: 'right center', flexShrink: 0 }}>
      {logo ? (
        <Img src={logo} style={{ height: 24 * s, width: 'auto', maxWidth: 70 * s, objectFit: 'contain', display: 'block' }} />
      ) : (
        <div
          style={{
            width: 36 * s,
            height: 24 * s,
            borderRadius: 4 * s,
            border: `${1.2 * s}px dashed rgba(255,255,255,0.6)`,
            background: 'rgba(255,255,255,0.12)',
          }}
        />
      )}
    </div>
  );

  const footerLine = footer ? (
    <div
      style={{
        fontFamily: FONTS.body,
        fontWeight: 700,
        fontSize: 7 * s,
        letterSpacing: '0.04em',
        textTransform: 'uppercase',
        color: '#FFFFFF',
        opacity: fade(pFooter),
        transform: `translateY(${(1 - pFooter) * 12 * s}px)`,
      }}
    >
      {footer}
    </div>
  ) : null;

  const mainText = (
    <>
      {location ? (
        <div
          style={{
            fontFamily: FONTS.body,
            fontWeight: 700,
            fontSize: 9 * s,
            letterSpacing: '0.24em',
            textTransform: 'uppercase',
            color: '#FFFFFF',
            ...rise(pLoc, 30),
          }}
        >
          {location}
        </div>
      ) : null}
      {title ? (
        <div
          style={{
            marginTop: 6 * s,
            fontFamily: FONTS.display,
            fontWeight: 900,
            fontStyle: 'italic',
            fontSize: titleSize,
            lineHeight: 1.02,
            textTransform: 'uppercase',
            color: '#FFFFFF',
            textShadow: '0 2px 12px rgba(1,35,66,0.25)',
            wordBreak: 'break-word',
            ...rise(pTitle, 40),
          }}
        >
          {title}
        </div>
      ) : null}
      {specs ? (
        <div
          style={{
            marginTop: 5 * s,
            fontFamily: FONTS.body,
            fontWeight: 400,
            fontSize: 12 * s,
            lineHeight: 1.25,
            color: '#FFFFFF',
            ...rise(pSpecs, 30),
          }}
        >
          {specs}
        </div>
      ) : null}
      {cta ? (
        <div style={{ marginTop: 11 * s, maxWidth: '100%', transform: `scale(${pCta})`, transformOrigin: 'left center', opacity: fade(pCta) }}>
          <div style={pill(cta, 15 * s)}>{cta}</div>
        </div>
      ) : null}
    </>
  );

  return (
    <AbsoluteFill style={{ overflow: 'hidden' }}>
      {/* 1. hero photo */}
      <AbsoluteFill style={{ opacity: imgOpacity, transform: `scale(${imgScale})` }}>
        {src ? (
          <Img src={src} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        ) : (
          <AbsoluteFill style={{ background: PLACEHOLDER }} />
        )}
      </AbsoluteFill>

      {/* 2. tag pill */}
      {tag ? (
        <div
          style={{
            position: 'absolute',
            left: padX,
            top: H * (wide ? 0.1 : 0.13),
            maxWidth: W - padX * 2,
            opacity: fade(pTag),
            transform: `translateY(${(1 - pTag) * -70 * s}px)`,
          }}
        >
          <div style={{ ...pill(tag, 12 * s), textTransform: 'uppercase' }}>{tag}</div>
        </div>
      ) : null}

      {/* 4. angled blue band */}
      <AbsoluteFill
        style={{
          background: BLUE_GRADIENT,
          clipPath: clip,
          transform: `translateY(${(1 - pBand) * (H - bandRight)}px)`,
        }}
      />

      {/* 3. price box */}
      {price ? (
        <div
          style={{
            position: 'absolute',
            right: W * 0.068,
            top: bandRight,
            maxWidth: W * (wide ? 0.4 : 0.6),
            opacity: fade(pPrice),
            transform: `translateY(calc(-50% + ${(1 - pPrice) * -90 * s}px))`,
          }}
        >
          <div
            style={{
              background: '#FFFFFF',
              color: NAVY,
              fontFamily: FONTS.display,
              fontWeight: 900,
              fontStyle: 'italic',
              fontSize: priceSize,
              lineHeight: 1.1,
              padding: `${7 * s}px ${12 * s}px`,
              boxShadow: `0 ${6 * s}px ${18 * s}px rgba(1,35,66,0.25)`,
              wordBreak: 'break-word',
            }}
          >
            {price}
          </div>
        </div>
      ) : null}

      {/* 5-12. band content */}
      {wide ? (
        <div
          style={{
            position: 'absolute',
            left: padX,
            right: padX,
            top: bandLeft + 16 * s,
            display: 'flex',
            alignItems: 'flex-end',
            gap: 20 * s,
          }}
        >
          <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', alignItems: 'flex-start' }}>
            {mainText}
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 10 * s, flexShrink: 0, maxWidth: '40%' }}>
            {logoBox}
            {avatarRow}
            {footerLine}
          </div>
        </div>
      ) : (
        <div
          style={{
            position: 'absolute',
            left: padX,
            right: padX,
            top: bandLeft + 22 * s,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'flex-start',
          }}
        >
          {mainText}
          <div
            style={{
              marginTop: 12 * s,
              width: '100%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 12 * s,
            }}
          >
            {avatarRow}
            {logoBox}
          </div>
          {footerLine ? <div style={{ marginTop: 12 * s }}>{footerLine}</div> : null}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default ImovelRevelacao;

