import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const BLUE = "#05B8E6";
const CORAL = "#F06052";
const INK = "#213D56";
const WHITE = "#FFFFFF";
const PHOTO_BG = "#EEF0EF";
const AVATAR_BG = "#B4B7B8";

// Font size that keeps `text` within `avail` px (rough glyph-width estimate).
const fit = (text: string, base: number, avail: number, k = 0.62): number =>
  Math.min(base, avail / (Math.max(1, text.length) * k));

const ImovelNovoStory: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));

  const p = anim.params ?? {};
  const str = (k: string): string => {
    const v = (p as Record<string, unknown>)[k];
    return v == null ? "" : String(v).trim();
  };
  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = str("tag");
  const price = str("price");
  const location = str("location");
  const title = str("title") || String(anim.text ?? "").trim();
  const facts = str("facts");
  const cta = str("cta");
  const name = str("name");
  const logoText = str("logoText");
  const logoSub = str("logoSub");
  const legal = str("legal");

  const side = format !== "portrait";
  const u =
    format === "portrait"
      ? W / 1080
      : format === "half"
        ? Math.min(W / 1080, H / 960) * 0.78
        : Math.min(W / 1920, H / 1080);

  // Staggered springs; each settles 12% of the layer after it starts, so all is still by 60%.
  const dur = Math.max(1, Math.round(0.12 * L));
  const at = (start: number, bouncy = true): number =>
    spring({
      frame: f - Math.round(start * L),
      fps,
      durationInFrames: dur,
      config: bouncy ? { damping: 9, stiffness: 140, mass: 0.8 } : { damping: 200 },
    });
  const fade = (s: number): number => Math.max(0, Math.min(1, s * 2));

  const reveal = interpolate(f, [0, Math.max(1, Math.round(0.2 * L))], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const sPanel = at(0.15, false);
  const sTag = at(0.2);
  const sPrice = at(0.28);
  const sEyebrow = at(0.3, false);
  const sTitle = at(0.34);
  const sFacts = at(0.38, false);
  const sCta = at(0.42);
  const sAvatar = at(0.46);
  const sLogo = at(0.48);
  const sLegal = at(0.48, false);

  // Geometry per arrangement.
  const pw = format === "landscape" ? 0.5 : 0.44; // photo share in side layouts
  const d = H * 0.097; // half the horizontal travel of the ~11° vertical slash
  const seamTop = pw * W + d;
  const margin = (side ? 64 : 72) * u;
  const contentLeft = side ? seamTop + 56 * u : 0.066 * W;
  const contentRight = side ? margin : 0.066 * W;
  const contentW = W - contentLeft - contentRight;

  const longestWord = title.split(/\s+/).reduce((a, w) => (w.length > a.length ? w : a), "");
  const titleSize = fit(longestWord, 92 * u, contentW, 0.66);
  const ctaPad = 40 * u;
  const ctaSize = fit(cta, 52 * u, contentW - ctaPad * 2, 0.6);
  const priceAvail = side ? seamTop - 2 * d * 0.78 - margin : W * 0.87;
  const priceSize = fit(price, 84 * u, priceAvail - 80 * u, 0.66);

  const headline: React.CSSProperties = {
    fontFamily: FONTS.display,
    fontWeight: 800,
    fontStyle: "italic",
    textTransform: "uppercase",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: PHOTO_BG, overflow: "hidden" }}>
      {/* 1. Photo — top-down wipe with a settling zoom */}
      <AbsoluteFill
        style={{
          width: side ? seamTop + d : W,
          clipPath: `inset(0 0 ${(1 - reveal) * 100}% 0)`,
          overflow: "hidden",
        }}
      >
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: side ? "100%" : "64%",
              objectFit: "cover",
              transform: `scale(${1.18 - 0.18 * reveal})`,
            }}
          />
        ) : (
          <AbsoluteFill style={{ backgroundColor: PHOTO_BG }} />
        )}
      </AbsoluteFill>

      {/* 3. Blue panel with the slash */}
      <AbsoluteFill
        style={{
          backgroundColor: BLUE,
          clipPath: side
            ? `polygon(${seamTop}px 0, 100% 0, 100% 100%, ${pw * W - d}px 100%)`
            : "polygon(0 62.2%, 100% 57.2%, 100% 100%, 0 100%)",
          transform: side ? `translateX(${(1 - sPanel) * 70}%)` : `translateY(${(1 - sPanel) * 50}%)`,
        }}
      />

      {/* 2. Status pill */}
      {tag ? (
        <div
          style={{
            position: "absolute",
            left: side ? margin : 0.066 * W,
            top: side ? 0.08 * H : 0.129 * H,
            maxWidth: side ? seamTop - 2 * margin : W * 0.8,
            backgroundColor: CORAL,
            color: WHITE,
            borderRadius: 999,
            padding: `${14 * u}px ${34 * u}px`,
            fontSize: 40 * u,
            lineHeight: 1,
            ...headline,
            opacity: fade(sTag),
            transform: `translateY(${(1 - sTag) * -180 * u}px)`,
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* 4. Price tag on the seam */}
      {price ? (
        <div
          style={{
            position: "absolute",
            right: side ? W - (pw * W + d - 2 * d * 0.74) - 60 * u : 0.066 * W,
            top: side ? 0.74 * H : 0.541 * H,
            maxWidth: priceAvail,
            backgroundColor: WHITE,
            color: INK,
            padding: `${20 * u}px ${40 * u}px`,
            fontSize: priceSize,
            lineHeight: 1,
            textAlign: "center",
            fontFamily: FONTS.display,
            fontWeight: 800,
            fontStyle: "italic",
            transform: `scale(${Math.max(0, sPrice)})`,
            transformOrigin: "right center",
          }}
        >
          {price}
        </div>
      ) : null}

      {/* 5–12. Panel content */}
      <div
        style={{
          position: "absolute",
          left: contentLeft,
          right: contentRight,
          top: side ? 0 : 0.635 * H,
          bottom: side ? 0 : undefined,
          display: "flex",
          flexDirection: "column",
          justifyContent: side ? "center" : "flex-start",
          color: WHITE,
        }}
      >
        {location ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.14em",
              fontSize: 30 * u,
              lineHeight: 1,
              marginBottom: 16 * u,
              opacity: fade(sEyebrow),
              transform: `translateY(${(1 - sEyebrow) * 50 * u}px)`,
            }}
          >
            {location}
          </div>
        ) : null}
        {title ? (
          <div
            style={{
              ...headline,
              fontSize: titleSize,
              lineHeight: 0.98,
              overflowWrap: "break-word",
              marginBottom: 16 * u,
              opacity: fade(sTitle),
              transform: `translateY(${(1 - sTitle) * 80 * u}px)`,
            }}
          >
            {title}
          </div>
        ) : null}
        {facts ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 500,
              fontSize: 36 * u,
              lineHeight: 1.4,
              marginBottom: 28 * u,
              opacity: fade(sFacts),
              transform: `translateY(${(1 - sFacts) * 50 * u}px)`,
            }}
          >
            {facts}
          </div>
        ) : null}
        {cta ? (
          <div
            style={{
              alignSelf: "flex-start",
              maxWidth: "100%",
              backgroundColor: CORAL,
              borderRadius: 999,
              padding: `${18 * u}px ${ctaPad}px`,
              fontFamily: FONTS.display,
              fontWeight: 800,
              fontStyle: "italic",
              fontSize: ctaSize,
              lineHeight: 1.05,
              marginBottom: 34 * u,
              transform: `scale(${Math.max(0, sCta)})`,
              transformOrigin: "left center",
            }}
          >
            {cta}
          </div>
        ) : null}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 24 * u,
            marginBottom: 28 * u,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 22 * u,
              opacity: fade(sAvatar),
              transform: `translateY(${(1 - sAvatar) * 70 * u}px)`,
            }}
          >
            <div
              style={{
                width: 74 * u,
                height: 74 * u,
                flexShrink: 0,
                borderRadius: "50%",
                border: `${4 * u}px solid ${WHITE}`,
                backgroundColor: AVATAR_BG,
                overflow: "hidden",
                boxSizing: "border-box",
              }}
            >
              {avatar ? (
                <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : null}
            </div>
            {name ? (
              <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 34 * u, lineHeight: 1.2 }}>
                {name}
              </div>
            ) : null}
          </div>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              flexShrink: 0,
              opacity: fade(sLogo),
              transform: `translateY(${(1 - sLogo) * -60 * u}px) scale(${Math.max(0, sLogo)})`,
            }}
          >
            {logo ? (
              <Img src={logo} style={{ height: 70 * u, width: "auto" }} />
            ) : (
              <>
                {logoText ? (
                  <div style={{ fontFamily: FONTS.body, fontWeight: 800, fontSize: 60 * u, lineHeight: 0.9, letterSpacing: "-0.02em" }}>
                    {logoText}
                  </div>
                ) : null}
                {logoSub ? (
                  <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 12 * u, lineHeight: 1.2, letterSpacing: "0.08em" }}>
                    {logoSub}
                  </div>
                ) : null}
              </>
            )}
          </div>
        </div>
        {legal ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.04em",
              fontSize: 19 * u,
              lineHeight: 1.2,
              opacity: fade(sLegal),
              transform: `translateY(${(1 - sLegal) * 30 * u}px)`,
            }}
          >
            {legal}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelNovoStory;

// ELEMENTS:
// 1. Foto do imóvel a ocupar o quadro inteiro (src) — entra primeiro
// 2. Pill coral "NOVO IMÓVEL" no topo à esquerda (tag)
// 3. Etiqueta de preço branca, cantos retos, na costura à direita (price)
// 4. Painel azul com o corte diagonal no topo, a subir para a direita
// 5. Eyebrow de localização "LISBOA · ALVALADE" (location)
// 6. Título "T3 COM VARANDA" 800 itálico maiúsculas (title / anim.text)
// 7. Linha de factos "120 m² · 3 quartos · 2 WC · garagem" (facts)
// 8. Pill CTA coral "Ligue já +351 963 050 290" (cta)
// 9. Avatar circular com anel branco (avatar)
// 10. Nome do agente "Manuel Reis" (name)
// 11. Logótipo da rede à direita (logo, ou logoText + logoSub)
// 12. Linha legal "IAD PORTUGAL S.A. | AMI: 11220" (legal)
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const PRIMARY = "#05B8E6";
const ACCENT = "#F06052";
const INK = "#213D56";
const WHITE = "#FFFFFF";
const PHOTO_BG = "#EEF0EF";
const AVATAR_BG = "#B4B7B8";

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ImovelStoryReveal: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const frame = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const params: Record<string, unknown> = anim.params ?? {};
  const s = (key: string): string => {
    const v = params[key];
    return typeof v === "string" ? v.trim() : typeof v === "number" ? String(v) : "";
  };

  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = s("tag");
  const price = s("price");
  const location = s("location");
  const title = s("title") || String(anim.text ?? "").trim();
  const facts = s("facts");
  const cta = s("cta");
  const name = s("name");
  const legal = s("legal");
  const logoText = s("logoText");
  const logoSub = s("logoSub");

  // Layout: k converts mockup px (363 wide portrait) into frame px.
  const portrait = format === "portrait";
  const land = format === "landscape";
  const k = portrait ? W / 363 : land ? H / 490 : H / 480;
  const mx = 24 * k;
  const seamL = (portrait ? 0.617 : land ? 0.6 : 0.53) * H;
  const seamR = (portrait ? 0.572 : land ? 0.49 : 0.44) * H;
  const tagTop = portrait ? 0.13 * H : 0.08 * H;
  const bottomPad = portrait ? 60 * k : 24 * k;

  const colW = W - 2 * mx;
  const headBase = 28 * k;
  const fitChars = (colW / (headBase * 0.7)) * (land ? 1 : 2);
  const headSize = title.length > fitChars ? Math.max(0.55, fitChars / title.length) * headBase : headBase;

  // Timing: everything settles by 60% of the layer.
  const T = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const at = (f: number) => Math.round(f * T);
  const pop = (start: number, len: number, damping = 12) =>
    spring({
      frame: frame - at(start),
      fps,
      durationInFrames: Math.max(2, at(len)),
      config: { damping, mass: 0.7, stiffness: 140 },
    });
  const move = (p: number, dy: number, scale = false): React.CSSProperties => ({
    opacity: interpolate(p, [0, 0.35], [0, 1], clamp),
    transform: `translateY(${(1 - p) * dy}px)${scale ? ` scale(${0.6 + 0.4 * p})` : ""}`,
  });

  const heroIris = interpolate(frame, [0, at(0.2)], [50, 0], clamp);
  const heroScale = interpolate(frame, [0, at(0.36)], [1.18, 1], clamp);
  const pPanel = pop(0.16, 0.18, 18);
  const pTag = pop(0.24, 0.14, 10);
  const pPrice = pop(0.3, 0.14, 10);
  const pEyebrow = pop(0.32, 0.12, 18);
  const pHead = pop(0.35, 0.13, 14);
  const pFacts = pop(0.39, 0.12, 18);
  const pCta = pop(0.43, 0.13, 9);
  const pFooter = pop(0.47, 0.12, 12);
  const pLegal = pop(0.5, 0.1, 18);

  const ctaEl = cta ? (
    <div
      style={{
        alignSelf: land ? "center" : "flex-start",
        background: ACCENT,
        color: WHITE,
        borderRadius: 999,
        padding: `${6 * k}px ${14 * k}px`,
        fontFamily: FONTS.body,
        fontWeight: 800,
        fontStyle: "italic",
        fontSize: 16 * k,
        lineHeight: 1.1,
        transformOrigin: "left center",
        ...move(pCta, 30 * k, true),
      }}
    >
      {cta}
    </div>
  ) : null;

  const logoEl = logo ? (
    <Img src={logo} style={{ height: 26 * k, width: "auto", objectFit: "contain" }} />
  ) : logoText ? (
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", color: WHITE, fontFamily: FONTS.body, lineHeight: 0.9 }}>
      <span style={{ fontWeight: 800, fontSize: 20 * k, letterSpacing: "-0.02em" }}>{logoText}</span>
      {logoSub ? (
        <span style={{ fontWeight: 700, fontSize: 4.6 * k, letterSpacing: "0.08em", textTransform: "uppercase", marginTop: 1.5 * k }}>
          {logoSub}
        </span>
      ) : null}
    </div>
  ) : (
    <div style={{ width: 40 * k, height: 22 * k, background: "rgba(255,255,255,0.25)" }} />
  );

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {/* 1. Hero photo */}
      <AbsoluteFill style={{ clipPath: `inset(${heroIris}% ${heroIris}% ${heroIris}% ${heroIris}%)` }}>
        <AbsoluteFill style={{ transform: `scale(${heroScale})` }}>
          {src ? (
            <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          ) : (
            <AbsoluteFill style={{ background: PHOTO_BG, justifyContent: "center", alignItems: "center" }}>
              <div style={{ width: 0.16 * Math.min(W, H), height: 0.1 * Math.min(W, H), background: "rgba(33,61,86,0.06)" }} />
            </AbsoluteFill>
          )}
        </AbsoluteFill>
      </AbsoluteFill>

      {/* 4. Primary panel with the slash */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: seamR,
          width: W,
          height: H - seamR + 80 * k,
          background: PRIMARY,
          clipPath: `polygon(0 ${seamL - seamR}px, 100% 0, 100% 100%, 0 100%)`,
          transform: `translateY(${(1 - pPanel) * (H - seamR + 40 * k)}px)`,
        }}
      />

      {/* 2. Status pill */}
      {tag ? (
        <div
          style={{
            position: "absolute",
            left: mx,
            top: tagTop,
            maxWidth: colW,
            background: ACCENT,
            color: WHITE,
            borderRadius: 999,
            padding: `${5 * k}px ${13 * k}px`,
            fontFamily: FONTS.body,
            fontWeight: 800,
            fontStyle: "italic",
            textTransform: "uppercase",
            fontSize: 12.5 * k,
            lineHeight: 1.1,
            ...move(pTag, -(tagTop + 40 * k)),
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* 3. Price tag on the seam */}
      {price ? (
        <div
          style={{
            position: "absolute",
            right: mx,
            top: seamR - 22 * k,
            maxWidth: colW,
            background: WHITE,
            color: INK,
            padding: `${7 * k}px ${14 * k}px`,
            fontFamily: FONTS.body,
            fontWeight: 800,
            fontStyle: "italic",
            fontSize: 27 * k,
            lineHeight: 1.15,
            textAlign: "right",
            ...move(pPrice, -120 * k),
          }}
        >
          {price}
        </div>
      ) : null}

      {/* 5-12. Panel content, anchored to the bottom */}
      <div
        style={{
          position: "absolute",
          left: mx,
          right: mx,
          bottom: bottomPad,
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          color: WHITE,
          fontFamily: FONTS.body,
        }}
      >
        {location ? (
          <div
            style={{
              fontWeight: 600,
              fontSize: 9.5 * k,
              letterSpacing: "0.14em",
              textTransform: "uppercase",
              lineHeight: 1.2,
              marginBottom: 6 * k,
              ...move(pEyebrow, 24 * k),
            }}
          >
            {location}
          </div>
        ) : null}
        {title ? (
          <div
            style={{
              fontWeight: 800,
              fontStyle: "italic",
              textTransform: "uppercase",
              fontSize: headSize,
              lineHeight: 0.98,
              marginBottom: 6 * k,
              ...move(pHead, 36 * k),
            }}
          >
            {title}
          </div>
        ) : null}
        {facts ? (
          <div style={{ fontWeight: 500, fontSize: 11.5 * k, lineHeight: 1.3, ...move(pFacts, 24 * k) }}>{facts}</div>
        ) : null}
        {!land && ctaEl ? <div style={{ marginTop: 12 * k, display: "flex" }}>{ctaEl}</div> : null}

        <div
          style={{
            alignSelf: "stretch",
            display: "flex",
            alignItems: "center",
            gap: 8 * k,
            marginTop: 14 * k,
            ...move(pFooter, 24 * k),
          }}
        >
          <div
            style={{
              width: 26 * k,
              height: 26 * k,
              flexShrink: 0,
              borderRadius: "50%",
              border: `${1.5 * k}px solid ${WHITE}`,
              background: AVATAR_BG,
              overflow: "hidden",
            }}
          >
            {avatar ? <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
          </div>
          {name ? <div style={{ fontWeight: 700, fontSize: 11 * k, lineHeight: 1.2 }}>{name}</div> : null}
          {land && ctaEl ? <div style={{ marginLeft: 16 * k, display: "flex" }}>{ctaEl}</div> : null}
          <div style={{ marginLeft: "auto", flexShrink: 0 }}>{logoEl}</div>
        </div>

        {legal ? (
          <div
            style={{
              marginTop: 10 * k,
              fontWeight: 600,
              fontSize: 6.3 * k,
              letterSpacing: "0.04em",
              textTransform: "uppercase",
              lineHeight: 1.2,
              ...move(pLegal, 16 * k),
            }}
          >
            {legal}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelStoryReveal;

// ELEMENTS:
// 1. Foto do imóvel a ocupar o quadro inteiro (src) — entra primeiro, com zoom-out
// 2. Pill 'NOVO IMÓVEL' no topo à esquerda (tag) — cai de cima com ressalto
// 3. Caixa de preço clara, cantos quase retos, sobre o corte diagonal à direita (price)
// 4. Faixa de cor com o topo em diagonal (a subir para a direita) — sobe de baixo
// 5. Localização em maiúsculas espaçadas 'LISBOA · ALVALADE' (location)
// 6. Título 'T3 COM VARANDA' pesado, itálico, maiúsculas (anim.text / title)
// 7. Linha de características '120 m² · 3 quartos · 2 WC · garagem' (specs)
// 8. Pill CTA 'Ligue já +351 963 050 290' (cta)
// 9. Avatar circular do agente com anel claro, canto inferior esquerdo (avatar)
// 10. Nome do agente 'Manuel Reis' (agent)
// 11. Logótipo da rede à direita da linha do agente (logo)
// 12. Linha legal 'IAD PORTUGAL S.A. | AMI: 11220' (legal)
import React from 'react';
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from 'remotion';
import { COLORS, FONTS } from '../style-tokens';
import type { PrimitiveProps } from '../primitives';

const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;

const ImovelRevelacaoTema: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const frame = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const params: Record<string, unknown> = anim.params ?? {};
  const txt = (key: string): string => {
    const v = params[key];
    return typeof v === 'string' ? v.trim() : typeof v === 'number' ? String(v) : '';
  };

  const src = String(anim.params?.src ?? '');
  const avatar = String(anim.params?.avatar ?? '');
  const logo = String(anim.params?.logo ?? '');
  const title = (anim.text ?? '').trim() || txt('title');
  const tag = txt('tag');
  const price = txt('price');
  const location = txt('location');
  const specs = txt('specs');
  const cta = txt('cta');
  const agent = txt('agent');
  const legal = txt('legal');

  // Timing: photo first, then everything lands by 60% of the layer.
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const at = (f: number) => Math.round(L * f);
  const pop = (start: number, dur = 0.12, damping = 11) =>
    spring({
      frame: Math.max(0, frame - at(start)),
      fps,
      config: { damping, mass: 0.7, stiffness: 140 },
      durationInFrames: Math.max(1, at(dur)),
    });

  const isLand = format === 'landscape';
  const isHalf = format === 'half';
  const s = isLand
    ? Math.min(W / 1920, H / 1080) * 0.85
    : isHalf
      ? Math.min(W / 1080, H / 960) * 0.7
      : Math.min(W / 1080, H / 1920);
  const pad = 72 * s;
  const slantH = (isLand ? 90 : 70) * s;
  const titleScale = Math.min(1, Math.max(0.55, (isLand ? 22 : 15) / Math.max(1, title.length)));

  // 1. Photo
  const imgOpacity = interpolate(frame, [0, at(0.12)], [0, 1], clamp);
  const imgScale = interpolate(frame, [0, at(0.32)], [1.18, 1], { ...clamp, easing: Easing.out(Easing.cubic) });

  // Springs (low damping = bounce)
  const vTag = pop(0.14, 0.14, 9);
  const vBand = pop(0.18, 0.16, 14);
  const vPrice = pop(0.28, 0.14, 8);
  const vLoc = pop(0.3, 0.12, 14);
  const vTitle = pop(0.34, 0.12, 12);
  const vSpecs = pop(0.38, 0.12, 14);
  const vCta = pop(0.42, 0.12, 8);
  const vAgent = pop(0.46, 0.12, 10);
  const vLegal = pop(0.48, 0.12, 14);

  const rise = (v: number): React.CSSProperties => ({
    opacity: interpolate(v, [0, 0.4], [0, 1], clamp),
    transform: `translateY(${(1 - v) * 50 * s}px)`,
  });

  const light = COLORS.textOnDark;
  const display = FONTS.display;

  const locationEl = location ? (
    <div style={{ ...rise(vLoc), fontFamily: display, fontWeight: 700, fontSize: 28 * s, letterSpacing: '0.24em', textTransform: 'uppercase', color: light, opacity: 0.9 * Math.min(1, vLoc * 2.5) }}>
      {location}
    </div>
  ) : null;

  const titleEl = title ? (
    <div style={{ ...rise(vTitle), fontFamily: display, fontWeight: 800, fontStyle: 'italic', fontSize: 92 * s * titleScale, lineHeight: 1.02, textTransform: 'uppercase', letterSpacing: '0.01em', color: light, marginTop: 10 * s, overflowWrap: 'break-word' }}>
      {title}
    </div>
  ) : null;

  const specsEl = specs ? (
    <div style={{ ...rise(vSpecs), fontFamily: display, fontWeight: 500, fontSize: 38 * s, lineHeight: 1.25, color: light, marginTop: 12 * s }}>
      {specs}
    </div>
  ) : null;

  const ctaEl = cta ? (
    <div
      style={{
        opacity: interpolate(vCta, [0, 0.3], [0, 1], clamp),
        transform: `scale(${interpolate(vCta, [0, 1], [0.4, 1])})`,
        transformOrigin: isLand ? 'right center' : 'left center',
        alignSelf: isLand ? 'flex-end' : 'flex-start',
        maxWidth: '100%',
        background: COLORS.teal,
        color: light,
        fontFamily: display,
        fontWeight: 700,
        fontStyle: 'italic',
        fontSize: 46 * s,
        lineHeight: 1.15,
        padding: `${16 * s}px ${40 * s}px`,
        borderRadius: 999,
        boxShadow: '0 6px 18px rgba(0,0,0,0.18)',
      }}
    >
      {cta}
    </div>
  ) : null;

  const initials = agent
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => (w[0] ?? '').toUpperCase())
    .join('');
  const av = 76 * s;
  const agentEl = (
    <div style={{ ...rise(vAgent), display: 'flex', alignItems: 'center', gap: 22 * s }}>
      <div
        style={{
          width: av,
          height: av,
          flexShrink: 0,
          borderRadius: '50%',
          border: `${4 * s}px solid ${light}`,
          overflow: 'hidden',
          background: COLORS.vellum,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          transform: `scale(${interpolate(vAgent, [0, 1], [0.3, 1])})`,
        }}
      >
        {avatar ? (
          <Img src={avatar} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        ) : (
          <span style={{ fontFamily: display, fontWeight: 700, fontSize: 26 * s, color: COLORS.mutedOnLight }}>{initials}</span>
        )}
      </div>
      {agent ? (
        <div style={{ fontFamily: display, fontWeight: 700, fontSize: 34 * s, color: light }}>{agent}</div>
      ) : null}
    </div>
  );

  const logoEl = (
    <div style={{ ...rise(vAgent), flexShrink: 0 }}>
      {logo ? (
        <Img src={logo} style={{ height: 70 * s, width: 'auto', objectFit: 'contain' }} />
      ) : (
        <div style={{ width: 120 * s, height: 64 * s, borderRadius: 8 * s, border: `${2 * s}px solid ${light}`, opacity: 0.5 }} />
      )}
    </div>
  );

  const legalEl = legal ? (
    <div style={{ ...rise(vLegal), fontFamily: display, fontWeight: 700, fontSize: 20 * s, letterSpacing: '0.04em', textTransform: 'uppercase', color: light, opacity: 0.85 * Math.min(1, vLegal * 2.5) }}>
      {legal}
    </div>
  ) : null;

  const gap = 30 * s;
  let content: React.ReactNode;
  if (isLand) {
    content = (
      <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'flex-end', justifyContent: 'space-between', gap: gap * 2 }}>
        <div style={{ flex: '1 1 45%', minWidth: 0 }}>
          {locationEl}
          {titleEl}
          {specsEl}
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: gap * 0.8, maxWidth: '50%' }}>
          {ctaEl}
          <div style={{ display: 'flex', alignItems: 'center', gap: gap * 1.4 }}>
            {agentEl}
            {logoEl}
          </div>
          {legalEl}
        </div>
      </div>
    );
  } else if (isHalf) {
    content = (
      <div style={{ display: 'flex', flexDirection: 'column' }}>
        {locationEl}
        {titleEl}
        {specsEl}
        <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap, marginTop: gap }}>
          {ctaEl}
          {agentEl}
        </div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap, marginTop: gap * 0.6 }}>
          {legalEl ?? <div />}
          {logoEl}
        </div>
      </div>
    );
  } else {
    content = (
      <div style={{ display: 'flex', flexDirection: 'column' }}>
        {locationEl}
        {titleEl}
        {specsEl}
        <div style={{ marginTop: gap * 1.1, display: 'flex' }}>{ctaEl}</div>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap, marginTop: gap * 1.3 }}>
          {agentEl}
          {logoEl}
        </div>
        {legalEl ? <div style={{ marginTop: gap * 0.9 }}>{legalEl}</div> : null}
      </div>
    );
  }

  // Band paint continues below the frame so its bounce never opens a gap.
  const overshoot = 80 * s;

  return (
    <AbsoluteFill style={{ overflow: 'hidden' }}>
      {/* 1. Photo — fills the whole box */}
      <AbsoluteFill style={{ opacity: imgOpacity, transform: `scale(${imgScale})` }}>
        {src ? (
          <Img src={src} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        ) : (
          <AbsoluteFill style={{ background: COLORS.vellum, alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ width: W * 0.3, height: W * 0.2, borderRadius: 12 * s, border: `${3 * s}px dashed ${COLORS.mutedOnLight}`, opacity: 0.6 }} />
          </AbsoluteFill>
        )}
      </AbsoluteFill>

      {/* 2. Tag pill — drops in from the top */}
      {tag ? (
        <div
          style={{
            position: 'absolute',
            top: H * (isLand ? 0.1 : isHalf ? 0.08 : 0.13),
            left: pad,
            maxWidth: W - pad * 2,
            opacity: Math.min(1, vTag * 3),
            transform: `translateY(${(1 - vTag) * -300 * s}px)`,
            background: COLORS.teal,
            color: light,
            fontFamily: display,
            fontWeight: 800,
            fontStyle: 'italic',
            textTransform: 'uppercase',
            fontSize: 40 * s,
            lineHeight: 1.15,
            padding: `${12 * s}px ${34 * s}px`,
            borderRadius: 999,
            boxShadow: '0 6px 18px rgba(0,0,0,0.25)',
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* 3–12. Bottom band — rises from below */}
      <AbsoluteFill style={{ justifyContent: 'flex-end' }}>
        <div style={{ transform: `translateY(${(1 - vBand) * 110}%)`, marginBottom: -overshoot }}>
          <div style={{ position: 'relative', height: slantH }}>
            <div style={{ position: 'absolute', left: 0, right: 0, top: 0, bottom: -1, background: COLORS.leather, clipPath: 'polygon(0 100%, 100% 0, 100% 100%)' }} />
            {price ? (
              <div
                style={{
                  position: 'absolute',
                  right: pad,
                  bottom: slantH * 0.05,
                  maxWidth: W - pad * 2,
                  opacity: interpolate(vPrice, [0, 0.3], [0, 1], clamp),
                  transform: `scale(${interpolate(vPrice, [0, 1], [0.3, 1])})`,
                  transformOrigin: 'right bottom',
                  background: light,
                  color: COLORS.ink,
                  fontFamily: display,
                  fontWeight: 800,
                  fontStyle: 'italic',
                  fontSize: 78 * s,
                  lineHeight: 1.1,
                  padding: `${14 * s}px ${38 * s}px`,
                  borderRadius: 4 * s,
                  boxShadow: '0 8px 22px rgba(0,0,0,0.22)',
                  overflowWrap: 'break-word',
                }}
              >
                {price}
              </div>
            ) : null}
          </div>
          <div style={{ background: COLORS.leather, padding: `${pad * 0.5}px ${pad}px ${pad * 0.6 + overshoot}px` }}>
            {content}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ImovelRevelacaoTema;

// ELEMENTS (mockup, top to bottom):
// 1. Full-frame property photo (src) - fills the whole box, everything else sits on top
// 2. Tag pill top-left ("NOVO IMÓVEL"): solid accent pill, heavy italic caps, light text
// 3. Price box ("450.000 €"): light rectangle on the right, sitting on the band's top edge, heavy italic dark text
// 4. Bottom band with a slanted top edge (higher on the right): golden gradient
// 5. Location line ("LISBOA · ALVALADE"): small caps, wide tracking
// 6. Headline ("T3 COM VARANDA"): heavy italic caps
// 7. Details line ("120 m² · 3 quartos · 2 WC · garagem"): regular body
// 8. Call-to-action pill ("Ligue já +351 963 050 290"): accent pill, bold italic light text
// 9. Agent avatar circle with a ring (avatar), bottom-left
// 10. Agent name ("Manuel Reis"), bold, next to the avatar
// 11. Brokerage logo (logo), bottom-right
// 12. Legal small print ("IAD PORTUGAL S.A. | AMI: 11220"): tiny bold caps
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ImovelRevealFaixaDourada: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const params = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string): string => {
    const v = params[k];
    return v == null ? "" : String(v).trim();
  };

  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const title = String(anim.text ?? "").trim() || str("title");
  const tag = str("tag");
  const price = str("price");
  const location = str("location");
  const details = str("details");
  const cta = str("cta");
  const agent = str("agent");
  const legal = str("legal");

  const W = frame.width;
  const H = frame.height;
  const land = format === "landscape";
  const half = format === "half";
  // one design unit = 1px of the 1080x1920 mockup
  const u = land ? (H / 1080) * 0.85 : half ? Math.min(W / 1080, H / 960) * 0.62 : Math.min(W / 1080, H / 1920);

  // timing: fractions of the layer, everything settles by 0.6
  const at = (s: number) => s * L;
  const sp = (start: number, dur: number, damping: number) =>
    spring({
      frame: f - at(start),
      fps,
      config: { damping, stiffness: 120, mass: 0.9 },
      durationInFrames: Math.max(1, Math.round(at(dur))),
    });
  const rise = (start: number): React.CSSProperties => {
    const s = sp(start, 0.13, 200);
    return { opacity: s, transform: `translateY(${(1 - s) * 40 * u}px)` };
  };

  const imgIn = interpolate(f, [0, at(0.2)], [0, 1], { ...CLAMP, easing: Easing.out(Easing.cubic) });
  const imgZoom = interpolate(f, [0, at(0.6)], [1.12, 1], { ...CLAMP, easing: Easing.out(Easing.cubic) });
  const bandS = sp(0.16, 0.2, 200);
  const tagS = sp(0.22, 0.2, 9);
  const priceS = sp(0.28, 0.22, 10);
  const ctaS = sp(0.42, 0.16, 10);
  const avatarS = sp(0.46, 0.13, 9);

  const slant = (land ? 70 : 90) * u;
  const padX = land ? 0.04 * W : 0.065 * W;
  const titleScale = Math.max(0.55, Math.min(1, (land ? 26 : 15) / Math.max(1, title.length)));
  const lightText = COLORS.textOnDark;
  const bandText = COLORS.ink;
  const display: React.CSSProperties = {
    fontFamily: FONTS.display,
    fontWeight: Math.max(FONTS.displayWeight, 800),
    fontStyle: "italic",
    textTransform: "uppercase",
  };

  const textBlock = (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 * u, flex: 1, minWidth: 0 }}>
      {location ? (
        <div style={{ ...rise(0.3), fontFamily: FONTS.body, fontWeight: 700, fontSize: 30 * u, letterSpacing: "0.24em", textTransform: "uppercase", color: bandText }}>
          {location}
        </div>
      ) : null}
      {title ? (
        <div style={{ ...rise(0.34), ...display, fontSize: 104 * u * titleScale, lineHeight: 0.98, color: bandText, overflowWrap: "break-word" }}>
          {title}
        </div>
      ) : null}
      {details ? (
        <div style={{ ...rise(0.38), fontFamily: FONTS.body, fontWeight: FONTS.bodyWeight, fontSize: 34 * u, color: bandText }}>
          {details}
        </div>
      ) : null}
      {cta ? (
        <div
          style={{
            alignSelf: "flex-start",
            marginTop: 14 * u,
            padding: `${14 * u}px ${36 * u}px`,
            borderRadius: 999,
            background: COLORS.leather,
            color: lightText,
            fontFamily: FONTS.body,
            fontWeight: 800,
            fontStyle: "italic",
            fontSize: 42 * u,
            opacity: Math.min(1, ctaS * 3),
            transform: `scale(${ctaS})`,
            transformOrigin: "left center",
          }}
        >
          {cta}
        </div>
      ) : null}
    </div>
  );

  const logoEl = logo ? (
    <Img src={logo} style={{ height: 76 * u, maxWidth: 240 * u, objectFit: "contain" }} />
  ) : (
    <div style={{ width: 130 * u, height: 70 * u, borderRadius: 8 * u, border: `${3 * u}px solid ${bandText}`, opacity: 0.4 }} />
  );

  const agentRow = (
    <div style={{ display: "flex", alignItems: "center", gap: 22 * u }}>
      <div
        style={{
          width: 76 * u,
          height: 76 * u,
          borderRadius: "50%",
          overflow: "hidden",
          flexShrink: 0,
          border: `${4 * u}px solid ${lightText}`,
          background: COLORS.vellum,
          transform: `scale(${avatarS})`,
        }}
      >
        {avatar ? <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
      </div>
      {agent ? (
        <div style={{ ...rise(0.46), fontFamily: FONTS.body, fontWeight: 800, fontSize: 34 * u, color: bandText }}>{agent}</div>
      ) : null}
    </div>
  );

  const legalEl = legal ? (
    <div style={{ ...rise(0.47), fontFamily: FONTS.body, fontWeight: 800, fontSize: 20 * u, letterSpacing: "0.04em", textTransform: "uppercase", color: bandText }}>
      {legal}
    </div>
  ) : null;

  return (
    <AbsoluteFill>
      {/* 1. full-frame photo */}
      <AbsoluteFill style={{ opacity: imgIn, transform: `scale(${imgZoom})` }}>
        {src ? (
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <AbsoluteFill style={{ background: COLORS.vellum, alignItems: "center", justifyContent: "center" }}>
            <div style={{ width: 0.3 * Math.min(W, H), height: 0.22 * Math.min(W, H), border: `${4 * u}px dashed ${COLORS.mutedOnDark}`, borderRadius: 16 * u }} />
          </AbsoluteFill>
        )}
      </AbsoluteFill>

      {/* 2. tag pill */}
      {tag ? (
        <div
          style={{
            position: "absolute",
            top: (land ? 0.08 : half ? 0.07 : 0.13) * H,
            left: padX,
            padding: `${12 * u}px ${30 * u}px`,
            borderRadius: 999,
            background: COLORS.leather,
            color: lightText,
            fontFamily: FONTS.body,
            fontWeight: 800,
            fontStyle: "italic",
            fontSize: 38 * u,
            textTransform: "uppercase",
            opacity: Math.min(1, tagS * 3),
            transform: `translateY(${(1 - tagS) * -160 * u}px)`,
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* bottom stack: price box + slanted golden band */}
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, display: "flex", flexDirection: "column", alignItems: "flex-end" }}>
        {price ? (
          <div
            style={{
              position: "relative",
              zIndex: 2,
              marginRight: land ? 0.04 * W : 0.065 * W,
              marginBottom: -slant * 0.45,
              padding: `${16 * u}px ${44 * u}px`,
              background: lightText,
              color: COLORS.ink,
              ...display,
              fontSize: 82 * u,
              lineHeight: 1.05,
              opacity: Math.min(1, priceS * 3),
              transform: `scale(${priceS})`,
              transformOrigin: "right bottom",
            }}
          >
            {price}
          </div>
        ) : null}
        <div
          style={{
            alignSelf: "stretch",
            background: headlineGradient(),
            clipPath: `polygon(0 ${slant}px, 100% 0, 100% 100%, 0 100%)`,
            padding: `${slant + 40 * u}px ${padX}px ${44 * u}px`,
            transform: `translateY(${(1 - bandS) * 110}%)`,
            display: "flex",
            flexDirection: land ? "row" : "column",
            alignItems: land ? "flex-end" : "stretch",
            gap: (land ? 60 : 30) * u,
          }}
        >
          {textBlock}
          {land ? (
            <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 24 * u, flexShrink: 0 }}>
              <div style={rise(0.46)}>{logoEl}</div>
              {agentRow}
              {legalEl}
            </div>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: 22 * u }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 24 * u }}>
                {agentRow}
                <div style={rise(0.46)}>{logoEl}</div>
              </div>
              {legalEl}
            </div>
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ImovelRevealFaixaDourada;

// ELEMENTS (mockup, top to bottom):
// 1. Full-frame property photo (params.src) - the backdrop of everything
// 2. Coral pill top-left "NOVO IMÓVEL" (white, heavy italic, caps)
// 3. White price box on the right, straddling the band edge, "450.000 €" (navy, heavy italic)
// 4. Angled bottom band (left edge lower than right) - gold-only gradient
// 5. Location line "LISBOA · ALVALADE" (small, white, wide tracking, caps)
// 6. Title "T3 COM VARANDA" (white, heavy italic, caps)
// 7. Features line "120 m² · 3 quartos · 2 WC · garagem" (white, regular)
// 8. Coral CTA pill "Ligue já +351 963 050 290" (white, bold italic)
// 9. Agent avatar circle (params.avatar) bottom-left
// 10. Agent name "Manuel Reis" (white, bold)
// 11. Brand logo bottom-right (params.logo)
// 12. Small print "IAD PORTUGAL S.A. | AMI: 11220" (tiny, white, caps)
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CORAL = "#EF6555";
const NAVY = "#24313D";
const GOLD_BAND = "linear-gradient(165deg, #DCC38E 0%, #C9AD76 35%, #A08A5C 75%, #7E6A42 100%)";
const ON_GOLD_SHADOW = "0 3px 14px rgba(70,52,24,0.45)";

const ImovelRevealDourado: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const frame = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const p = anim.params ?? {};
  const str = (k: string) => String((p as Record<string, unknown>)[k] ?? "").trim();

  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const badge = str("badge");
  const price = str("price");
  const location = str("location");
  const title = str("title") || String(anim.text ?? "").trim();
  const features = str("features");
  const cta = str("cta");
  const agentName = str("agentName");
  const footer = str("footer");

  const wide = format !== "portrait";
  // scale unit relative to the 1080-wide portrait mockup
  const u =
    format === "portrait"
      ? W / 1080
      : format === "half"
        ? Math.min(W / 1080, H / 960) * 0.78
        : Math.min(W / 1920, H / 1080) * 0.85;

  // band geometry: left edge lower than right edge
  const bandL = H * (format === "portrait" ? 0.614 : format === "half" ? 0.5 : 0.56);
  const bandR = H * (format === "portrait" ? 0.575 : format === "half" ? 0.44 : 0.48);
  const slant = bandL - bandR;
  const pad = W * (format === "landscape" ? 0.045 : 0.069);

  // timing - everything settled by 60% of the layer
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const at = (f: number) => Math.round(f * L);
  const ease = (s: number, d: number) =>
    interpolate(frame, [at(s), at(s) + Math.max(1, at(d))], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.16, 1, 0.3, 1),
    });
  const pop = (s: number, d: number, damping = 11) =>
    spring({
      frame: frame - at(s),
      fps,
      durationInFrames: Math.max(1, at(d)),
      config: { damping, stiffness: 140, mass: 0.8 },
    });
  const op = (v: number) => Math.max(0, Math.min(1, v));

  const imgIn = ease(0, 0.14);
  const imgScale = interpolate(frame, [0, Math.max(1, at(0.6))], [1.15, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const band = ease(0.12, 0.16);
  const pillP = pop(0.2, 0.18);
  const priceP = pop(0.27, 0.16, 9);
  const locP = ease(0.3, 0.12);
  const titleP = pop(0.33, 0.16, 12);
  const featP = ease(0.37, 0.12);
  const ctaP = pop(0.41, 0.14, 9);
  const avP = pop(0.46, 0.12, 10);
  const nameP = ease(0.48, 0.1);
  const logoP = pop(0.5, 0.1, 10);
  const footP = ease(0.52, 0.08);

  // shrink long titles instead of clipping them
  const titleSize = 92 * u * Math.max(0.55, Math.min(1, (wide ? 20 : 15) / Math.max(1, title.length)));
  const avatarD = 76 * u;

  const locationEl = location ? (
    <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 26 * u, letterSpacing: "0.24em", textTransform: "uppercase", color: "#FFFFFF", textShadow: ON_GOLD_SHADOW, opacity: locP, transform: `translateY(${(1 - locP) * 30 * u}px)` }}>
      {location}
    </div>
  ) : null;

  const titleEl = title ? (
    <div style={{ fontFamily: FONTS.body, fontWeight: 900, fontStyle: "italic", fontSize: titleSize, lineHeight: 1.02, textTransform: "uppercase", color: "#FFFFFF", textShadow: ON_GOLD_SHADOW, marginTop: 10 * u, overflowWrap: "break-word", opacity: op(titleP * 2), transform: `translateY(${(1 - titleP) * 80 * u}px)` }}>
      {title}
    </div>
  ) : null;

  const featuresEl = features ? (
    <div style={{ fontFamily: FONTS.body, fontWeight: 400, fontSize: 36 * u, color: "#FFFFFF", textShadow: ON_GOLD_SHADOW, marginTop: 10 * u, opacity: featP, transform: `translateY(${(1 - featP) * 24 * u}px)` }}>
      {features}
    </div>
  ) : null;

  const ctaEl = cta ? (
    <div style={{ alignSelf: wide ? "flex-end" : "flex-start", background: CORAL, borderRadius: 999, padding: `${16 * u}px ${44 * u}px`, fontFamily: FONTS.body, fontWeight: 800, fontStyle: "italic", fontSize: 46 * u, lineHeight: 1.15, color: "#FFFFFF", boxShadow: "0 6px 20px rgba(70,40,20,0.3)", marginTop: wide ? 0 : 30 * u, maxWidth: "100%", opacity: op(ctaP * 2), transform: `scale(${0.5 + 0.5 * ctaP})`, transformOrigin: wide ? "right center" : "left center" }}>
      {cta}
    </div>
  ) : null;

  const logoEl = (
    <div style={{ opacity: op(logoP * 2), transform: `scale(${0.4 + 0.6 * logoP})`, flexShrink: 0 }}>
      {logo ? (
        <Img src={logo} style={{ height: 80 * u, width: "auto", objectFit: "contain", display: "block" }} />
      ) : (
        <div style={{ width: 110 * u, height: 80 * u, borderRadius: 10 * u, background: "rgba(255,255,255,0.28)" }} />
      )}
    </div>
  );

  const agentEl = (
    <div style={{ display: "flex", alignItems: "center", gap: 22 * u }}>
      <div style={{ width: avatarD, height: avatarD, borderRadius: "50%", overflow: "hidden", flexShrink: 0, border: `${3 * u}px solid #FFFFFF`, background: "#D9D9D6", opacity: op(avP * 2), transform: `scale(${avP})` }}>
        {avatar ? <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
      </div>
      {agentName ? (
        <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 36 * u, color: "#FFFFFF", textShadow: ON_GOLD_SHADOW, opacity: nameP, transform: `translateX(${(1 - nameP) * -30 * u}px)` }}>
          {agentName}
        </div>
      ) : null}
    </div>
  );

  const footerEl = footer ? (
    <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 18 * u, letterSpacing: "0.06em", textTransform: "uppercase", color: "#FFFFFF", marginTop: 24 * u, opacity: footP, transform: `translateY(${(1 - footP) * 16 * u}px)` }}>
      {footer}
    </div>
  ) : null;

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {/* 1. hero photo */}
      <AbsoluteFill style={{ opacity: imgIn, transform: `scale(${imgScale})` }}>
        {src ? (
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <AbsoluteFill style={{ background: "#ECEEEE", alignItems: "center", justifyContent: "center" }}>
            <div style={{ width: W * 0.22, height: W * 0.16, borderRadius: 12 * u, border: `${4 * u}px solid #D3D7D7` }} />
          </AbsoluteFill>
        )}
      </AbsoluteFill>

      {/* 4. angled gold band */}
      <div style={{ position: "absolute", left: 0, right: 0, top: bandR, bottom: 0, background: GOLD_BAND, clipPath: `polygon(0 ${slant}px, 100% 0, 100% 100%, 0 100%)`, transform: `translateY(${(1 - band) * 100}%)` }} />

      {/* 2. badge pill */}
      {badge ? (
        <div style={{ position: "absolute", left: pad, top: H * (format === "portrait" ? 0.13 : format === "half" ? 0.08 : 0.1), background: CORAL, borderRadius: 999, padding: `${12 * u}px ${36 * u}px`, fontFamily: FONTS.body, fontWeight: 900, fontStyle: "italic", fontSize: 38 * u, lineHeight: 1.15, textTransform: "uppercase", color: "#FFFFFF", boxShadow: "0 6px 18px rgba(0,0,0,0.18)", maxWidth: W - pad * 2, opacity: op(pillP * 2), transform: `translateY(${(1 - pillP) * -220 * u}px)` }}>
          {badge}
        </div>
      ) : null}

      {/* 3. price box */}
      {price ? (
        <div style={{ position: "absolute", right: pad, top: bandR, background: "#FFFFFF", padding: `${20 * u}px ${44 * u}px`, fontFamily: FONTS.body, fontWeight: 900, fontStyle: "italic", fontSize: 84 * u, lineHeight: 1.05, color: NAVY, boxShadow: "0 8px 24px rgba(0,0,0,0.2)", maxWidth: W * 0.7, textAlign: "center", opacity: op(priceP * 2), transform: `translateY(-55%) scale(${0.4 + 0.6 * priceP})`, transformOrigin: "right center" }}>
          {price}
        </div>
      ) : null}

      {/* band content */}
      <div style={{ position: "absolute", left: pad, right: pad, top: bandL + H * (wide ? 0.05 : 0.02), bottom: H * 0.03, display: "flex", flexDirection: "column" }}>
        {wide ? (
          <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 40 * u }}>
            <div style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column" }}>
              {locationEl}
              {titleEl}
              {featuresEl}
            </div>
            <div style={{ flexShrink: 1, maxWidth: "48%", display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 26 * u }}>
              {ctaEl}
              <div style={{ display: "flex", alignItems: "center", gap: 40 * u }}>
                {agentEl}
                {logoEl}
              </div>
            </div>
          </div>
        ) : (
          <>
            {locationEl}
            {titleEl}
            {featuresEl}
            {ctaEl}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 36 * u, gap: 20 * u }}>
              {agentEl}
              {logoEl}
            </div>
          </>
        )}
        {footerEl}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelRevealDourado;
